// TH18 v1.00a Stage 5 BossCard3 (spell 52), st05bs.ecl.txt:832-900.
// Source t0 starts after the 120-frame shell buffer; first fire is at source t120.
const TIME_LIMIT: int = 3120; // 120 buffer + 2700 source spell timer + 300 tail
const SOURCE_LIMIT: int = 2700;
const TH18_BIG_BALL2: int = 656;       // etSprite(0,19,1)
const TH18_FIREBALL_RED: int = 752;    // SHOOT_DATA sprite25, color0
const TH18_FIREBALL_PURPLE: int = 768; // SHOOT_DATA sprite26, color0

// Source 913 OFFSCREEN(200,0). Parent EX must survive offscreen to finish its chain.
xformdef KEEP_PARENT(keep: int) {
    offscreen_keep(keep);
}

// Source SHOOT mode1 fixed fan, current parent angle as centre, 45deg step.
// Counts: first/second block Easy1 Normal3 Hard4; Lunatic 4/5.
sub parent_fan(n: int, shape: int) {
    var center: angle = $self_angle;
    for i in 0..n {
        var off: int = 0;
        if n % 2 == 1 {
            off = ((i+1)/2)*8192;
            if i % 2 != 0 { off = -off; }
        } else {
            off = (i/2)*8192+4096;
            if i % 2 != 0 { off = -off; }
        }
        _ = fire(shape, 0, $self_x, $self_y, 0.8fx,
                 center + (off as angle), none, none);
    }
}

// Source BossCard3_at 912-966 EX chain on each of the 5 parent bullets.
// Task starts one frame after birth: t = source tick - 1.
// 2 WAIT7+SHOOT pairs, GOTO(index1,2) => 3 passes; STEP 30 frames c1;
// then 4 passes of WAIT8+SHOOT pair, GOTO(index10,3).
// F0 is 0/-0, so STEP r=%F0 is 0: boundary angle = player angle, speed 3.
async sub parent_ex() {
    var rank: int = global(GVAR_RANK);
    var c1: int = 1;
    var c2: int = 1;
    if rank == 1 { c1 = 3; c2 = 3; }
    if rank == 2 { c1 = 4; c2 = 4; }
    if rank == 3 { c1 = 4; c2 = 5; }
    for t in 0..106 {
        if t == 6 { parent_fan(c1, TH18_FIREBALL_RED); }
        if t == 13 { parent_fan(c1, TH18_FIREBALL_PURPLE); }
        if t == 20 { parent_fan(c1, TH18_FIREBALL_RED); }
        if t == 27 { parent_fan(c1, TH18_FIREBALL_PURPLE); }
        if t == 34 { parent_fan(c1, TH18_FIREBALL_RED); }
        if t == 41 { parent_fan(c1, TH18_FIREBALL_PURPLE); }
        if t == 49 { parent_fan(c2, TH18_FIREBALL_RED); }
        if t == 57 { parent_fan(c2, TH18_FIREBALL_PURPLE); }
        if t == 65 { parent_fan(c2, TH18_FIREBALL_RED); }
        if t == 73 { parent_fan(c2, TH18_FIREBALL_PURPLE); }
        if t == 81 { parent_fan(c2, TH18_FIREBALL_RED); }
        if t == 89 { parent_fan(c2, TH18_FIREBALL_PURPLE); }
        if t == 97 { parent_fan(c2, TH18_FIREBALL_RED); }
        if t == 105 { parent_fan(c2, TH18_FIREBALL_PURPLE); }
        if t >= 41 && t < 71 {
            var k: int = t-41;
            set_speed(0, 4fx - 4fx*(k as fx)/30fx); // STEP a30 b1 c1 fall
        }
        if t == 71 {
            set_angle(0, aim_player()); // c1 boundary: player angle + r(0)
            set_speed(0, 3fx);
        }
        wait(1);
    }
}

// Source 906-911: N5 M1, mode5 half-step ring, base 90deg + RANDF2*10deg + 36deg.
// Source delta 20deg is the layer rotation; M=1 so it does not apply.
sub card_fire() {
    var off: int = ((rand(65536)-32768)*1820)/32768;
    var base: int = 16384 + 6554 + off;
    for i in 0..5 {
        _ = fire(TH18_BIG_BALL2, 1, $self_x, $self_y, 4fx,
                 (base + (i*65536)/5) as angle, KEEP_PARENT(200), parent_ex);
    }
}

async sub pattern() {
    wait(120); // shell buffer
    var until: int = $frame + SOURCE_LIMIT; // source spell timer starts here
    // Source 867: movePosTime(60,4,0,128); entry is already the source centre (0,128).
    move_to(60, 0fx, 128fx, EASE_QUAD_OUT);
    wait(60);
    wait(60); // source 869-880 +60 nop
    loop {
        if $frame >= until { return; }
        card_fire();
        var gap: int = 270;
        if global(GVAR_RANK) == 3 { gap = 230; }
        wait(gap);
        card_move_rand(); // source moveRand(50,0,0.8): 50-frame motion
        for i in 0..10 { wait(1); } // remainder of source wait(60)
    }
}

async sub boss_main() {
    set_invuln(65535);
    set_hitbox(24fx);  // source setHitbox(48,48), ordinary circle half-width
    set_hurtbox(20fx); // source setHurtbox(40,40)
    spell_begin(0, 52, pattern, TIME_LIMIT, 0, 0, 0);
    wait_spell();
    loop { wait(1); }
}

// Source Boss() creates the boss at (0,128); the extra controller stays at (0,0)
// with body collision off, while the real boss keeps the source hit/hurt boxes.
async sub controller() {
    set_enemy_flag(ENEMY_NO_BODY, 1);
    set_invuln(65535);
    _ = spawn_enemy(0fx, 128fx, 100000, 0, 0, 0, boss_main);
    loop { wait(600); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1, 0, 0, 0, controller);
    loop { wait(600); }
}

// TH18 v1.00a BossCard3 moveRand(50,0,0.8) and moveLimit(0,128,200,64).
// Same recipe as the checked Stage01 moveRand helper, with speed 0.8 and
// x limit [-100,100], y limit [96,160]; direction inner region is width/4,
// so x thresholds are +/-50 (y keeps 112/144).
// Boss int slot0 = next movement step; fx0/fx1 = chosen unit direction.

sub card_arm_next_step() {
    var k: int = self_int(0)+1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 50 { speed = 0.8fx*((50-k) as fx)/50fx; }
    var nx: fx = $self_x+self_fx(0)*speed;
    var ny: fx = $self_y+self_fx(1)*speed;
    if nx < -100fx { nx = -100fx; }
    if nx > 100fx { nx = 100fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx-$self_x, ny-$self_y, EASE_LINEAR);
}

sub card_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card_arm_next_step();
}

sub card_move_rand() {
    var r: int = rand(65536)-32768;
    var a: int = 0;
    if $self_x < -50fx {
        a = r/3;
    } else if $self_x > 50fx {
        a = r/3+32768;
        if a > 32768 { a = a-65536; }
    } else {
        a = r/4;
        var choose: int = rand(65536)%3;
        if $player_x > $self_x {
            if choose == 0 { a = a+32768; }
        } else {
            if choose != 0 { a = a+32768; }
        }
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a as angle);
    for i in 0..50 {
        wait(1);
        card_arm_next_step();
    }
}
